//! Faint dot-matrix Wind mark above the text column of the welcome screen.
//!
//! The art is a precomputed braille mask (see `wind_mark_data.rs`, generated by `scripts/gen-wind-mark.py` from the Lucide "Wind" icon).
//! Every dot inside the shape is lit: the mark is a solid fill, made faint through colour alone.
//!
//! - Colour: a cool grey on the left, where the wind starts, warming to ember on the right, where it meets the fire. Each cell takes
//!   `base = mix(bg, fg, 0.08 + 0.08 * (1 - y/H))`, `warm = mix(bg, ember, 0.42)` and `mix(base, warm, 0.15 + 0.75 * (x/W)^1.5)`.
//! - At rest it faces forward with no extruded shadow.
//! - Spin (see `wind_spin.rs`): the mask turns about its vertical axis. Dot x becomes `cx + (x - cx) cos(t)`; three depth layers offset by
//!   `depth * sin(t)` are drawn behind the face, but only in cells that hold no face dot, because a cell has one colour and a face dot sharing
//!   a cell with shadow dots would stripe the stroke. The face dims with |cos(t)| (never brighter than at rest) and warms with max(0, sin(t)).
//! - Gust: an ember band sweeps left to right once as the mark settles.
//!
//! The mark is painted before every other welcome widget, so text drawn later always overwrites it.

use ratatui::buffer::Buffer;
use ratatui::layout::Rect;
use ratatui::style::Color;

use super::wind_mark_data::MASKS;
use super::wind_spin::Pose;
use crate::render::color::{blend_color, resolve_to_rgb};
use crate::theme::Theme;
use crate::theme::color_support::{self, ColorLevel};

/// Below this terminal size the mark is not drawn at all.
pub(super) const MIN_WIDTH: u16 = 70;
pub(super) const MIN_HEIGHT: u16 = 24;

/// Foreground mixed into the background: top row / bottom row of the rested face.
const LIT_TOP: f32 = 0.16;
const LIT_BOTTOM: f32 = 0.08;
/// Fraction of the rested brightness kept when the face is edge-on.
const EDGE_ON_KEEP: f32 = 0.5;
/// Ramp from cool grey (left) to warm ember (right): `warm` strength at the left edge, the extra toward the right edge, and its curve.
const WARM_MIX: f32 = 0.42;
const RAMP_LEFT: f32 = 0.15;
const RAMP_SPAN: f32 = 0.75;
const RAMP_CURVE: f32 = 1.5;
/// Light themes use a darker ember: this fraction of the way from ember to the background's inverse.
const LIGHT_EMBER_DARKEN: f32 = 0.30;
/// Extra ember on the face at a quarter turn, as it turns toward the light.
const SPIN_EMBER: f32 = 0.18;
/// Depth layers behind the face while spinning, and sideways dots per layer at a quarter turn.
const DEPTH_LAYERS: usize = 3;
const DEPTH_STEP: f32 = 1.5;
const SHADOW_DARK: f32 = 0.22;
const SHADOW_LIGHT: f32 = 0.08;
/// Gust: gaussian width (fraction of the mark width) and peak ember mix.
const GUST_SIGMA: f32 = 0.08;
const GUST_PEAK: f32 = 0.18;
/// Brand ember, `#FF6A1A`.
const EMBER: Color = Color::Rgb(0xFF, 0x6A, 0x1A);

/// Braille bit for the dot at `[dy][dx]` within a cell.
const BITS: [[u8; 2]; 4] = [[0x01, 0x08], [0x02, 0x10], [0x04, 0x20], [0x40, 0x80]];

/// Everything the painter needs; built from the live theme in [`paint_live`], explicit in tests.
#[derive(Clone, Copy, Debug)]
pub(super) struct MarkSpec {
    pub bg: Color,
    pub fg: Color,
    pub level: ColorLevel,
    pub pose: Pose,
}

/// Largest mask that fits `region`, or `None` when the screen is too small.
pub(super) fn pick_size(screen: Rect, region: Rect) -> Option<&'static (u16, u16, &'static str)> {
    if screen.width < MIN_WIDTH || screen.height < MIN_HEIGHT {
        return None;
    }
    MASKS
        .iter()
        .rev()
        .find(|(c, r, _)| *c <= region.width && *r <= region.height)
}

/// Row counts of the available masks, for tests.
#[cfg(test)]
pub(super) const MASKS_ROWS: [u16; 4] = [12, 16, 22, 30];

/// Rows the layout reserves for the mark: the height of the largest mask that fits `width` columns and `spare` rows, or 0 for none.
/// The painter picks the same mask from the slot, so the slot is exactly as tall as the mark.
pub(super) fn slot_rows(width: u16, spare: u16) -> u16 {
    if width < MIN_WIDTH {
        return 0;
    }
    MASKS
        .iter()
        .rev()
        .find(|(c, r, _)| *c <= width && *r <= spare)
        .map_or(0, |m| m.1)
}

/// The mask as a `(2 * cols) x (4 * rows)` grid of lit dots.
pub(super) fn decode(mask: &str, cols: usize, rows: usize) -> Vec<bool> {
    let w = cols * 2;
    let mut dots = vec![false; w * rows * 4];
    for (r, line) in mask.lines().enumerate().take(rows) {
        for (c, ch) in line.chars().enumerate().take(cols) {
            let v = (ch as u32).wrapping_sub(0x2800);
            if v >= 0x100 {
                continue;
            }
            for (dy, row) in BITS.iter().enumerate() {
                for (dx, bit) in row.iter().enumerate() {
                    if v as u8 & bit != 0 {
                        dots[(r * 4 + dy) * w + c * 2 + dx] = true;
                    }
                }
            }
        }
    }
    dots
}

/// Cell bit grids for one pose, `cols * rows` each.
pub(super) struct Composed {
    /// Braille bits of face dots.
    pub face: Vec<u8>,
    /// Mean source x (0..1 across the mask) of the face dots in the cell, for the colour ramp.
    pub src_x: Vec<f32>,
    /// Braille bits of depth-layer dots, only ever in cells whose `face` is 0.
    pub back: Vec<u8>,
}

pub(super) fn compose(dots: &[bool], cols: usize, rows: usize, theta: f32) -> Composed {
    let w = cols * 2;
    let cx = w as f32 / 2.0;
    // Exactly forward must not pick up float noise from cos/sin
    let (c, s) = if theta == 0.0 {
        (1.0, 0.0)
    } else {
        (theta.cos(), theta.sin())
    };
    let place = |x: usize, depth: usize| -> Option<usize> {
        let v = cx + (x as f32 + 0.5 - cx) * c + depth as f32 * DEPTH_STEP * s;
        (v >= 0.0 && v < w as f32).then_some(v as usize)
    };
    let mut face = vec![0u8; cols * rows];
    let mut src_sum = vec![0.0f32; cols * rows];
    let mut count = vec![0u16; cols * rows];
    for y in 0..rows * 4 {
        for x in 0..w {
            if !dots[y * w + x] {
                continue;
            }
            if let Some(sx) = place(x, 0) {
                let cell = (y / 4) * cols + sx / 2;
                face[cell] |= BITS[y % 4][sx % 2];
                src_sum[cell] += (x as f32 + 0.5) / w as f32;
                count[cell] += 1;
            }
        }
    }
    let src_x = src_sum
        .iter()
        .zip(&count)
        .enumerate()
        .map(|(i, (sum, n))| {
            if *n > 0 {
                sum / f32::from(*n)
            } else {
                ((i % cols) as f32 + 0.5) / cols as f32
            }
        })
        .collect();
    let mut back = vec![0u8; cols * rows];
    if s != 0.0 {
        for depth in 1..=DEPTH_LAYERS {
            for y in 0..rows * 4 {
                for x in 0..w {
                    if !dots[y * w + x] {
                        continue;
                    }
                    if let Some(sx) = place(x, depth) {
                        let cell = (y / 4) * cols + sx / 2;
                        if face[cell] == 0 {
                            back[cell] |= BITS[y % 4][sx % 2];
                        }
                    }
                }
            }
        }
    }
    Composed { face, src_x, back }
}

fn is_light(bg: Color) -> bool {
    resolve_to_rgb(bg).is_some_and(|(r, g, b)| {
        0.2126 * f32::from(r) + 0.7152 * f32::from(g) + 0.0722 * f32::from(b) > 127.0
    })
}

/// The ember used on this theme: brand ember on dark, a darker ember on light.
pub(super) fn ember_color(bg: Color) -> Option<Color> {
    if !is_light(bg) {
        return Some(EMBER);
    }
    let (r, g, b) = resolve_to_rgb(bg)?;
    blend_color(
        EMBER,
        Color::Rgb(255 - r, 255 - g, 255 - b),
        LIGHT_EMBER_DARKEN,
    )
}

fn gust_strength(u: f32, progress: f32) -> f32 {
    let centre = -3.0 * GUST_SIGMA + (1.0 + 6.0 * GUST_SIGMA) * progress;
    let d = (u - centre) / GUST_SIGMA;
    GUST_PEAK * (-0.5 * d * d).exp()
}

/// Face colour for a cell at `row_frac` down and `col_frac` across the mask. `None` means the terminal cannot blend (named ANSI colours).
pub(super) fn face_color(spec: &MarkSpec, row_frac: f32, col_frac: f32) -> Option<Color> {
    let theta = spec.pose.theta;
    let lit = (LIT_BOTTOM + (LIT_TOP - LIT_BOTTOM) * (1.0 - row_frac))
        * (EDGE_ON_KEEP + (1.0 - EDGE_ON_KEEP) * theta.cos().abs());
    let base = blend_color(spec.bg, spec.fg, lit)?;
    let ember = ember_color(spec.bg)?;
    let warm = blend_color(spec.bg, ember, WARM_MIX)?;
    let mut c = blend_color(
        base,
        warm,
        RAMP_LEFT + RAMP_SPAN * col_frac.clamp(0.0, 1.0).powf(RAMP_CURVE),
    )?;
    let turn = theta.sin().max(0.0);
    if turn > 0.0 {
        c = blend_color(c, ember, SPIN_EMBER * turn).unwrap_or(c);
    }
    if let Some(p) = spec.pose.gust {
        let s = gust_strength(col_frac, p);
        if s > 0.004 {
            c = blend_color(c, ember, s).unwrap_or(c);
        }
    }
    Some(c)
}

pub(super) fn shadow_color(spec: &MarkSpec) -> Option<Color> {
    let amount = if is_light(spec.bg) {
        SHADOW_LIGHT
    } else {
        SHADOW_DARK
    };
    blend_color(spec.bg, Color::Rgb(0, 0, 0), amount)
}

/// Paints the mark into `buf`, centred in `region`. Returns whether anything was drawn.
/// Only the glyph and foreground of mark cells are touched, so the background underneath is preserved.
pub(super) fn paint(buf: &mut Buffer, screen: Rect, region: Rect, spec: &MarkSpec) -> bool {
    if !spec.level.has_color() {
        return false;
    }
    let Some(&(cols, rows, mask)) = pick_size(screen, region) else {
        return false;
    };
    let (cols, rows) = (cols as usize, rows as usize);
    let dots = decode(mask, cols, rows);
    let comp = compose(&dots, cols, rows, spec.pose.theta);
    let origin_x = region.x + (region.width - cols as u16) / 2;
    let origin_y = region.y + (region.height - rows as u16) / 2;
    let fallback = Color::DarkGray;
    let shadow = shadow_color(spec);
    let blendable = blend_color(spec.bg, spec.fg, 0.1).is_some();
    let mut drew = false;
    for cr in 0..rows {
        for cc in 0..cols {
            let i = cr * cols + cc;
            let (bits, color) = if comp.face[i] != 0 {
                let row_frac = (cr as f32 + 0.5) / rows as f32;
                let c = if blendable {
                    face_color(spec, row_frac, comp.src_x[i]).unwrap_or(fallback)
                } else {
                    fallback
                };
                (comp.face[i], c)
            } else if comp.back[i] != 0 {
                match shadow {
                    Some(c) if blendable => (comp.back[i], c),
                    // Named ANSI colours cannot be shaded; skip the depth layers rather than guess.
                    _ => continue,
                }
            } else {
                continue;
            };
            let (x, y) = (origin_x + cc as u16, origin_y + cr as u16);
            if let Some(cell) = buf.cell_mut((x, y)) {
                cell.set_char(char::from_u32(0x2800 + u32::from(bits)).unwrap_or(' '));
                cell.set_fg(color);
                drew = true;
            }
        }
    }
    drew
}

fn no_color_env() -> bool {
    std::env::var_os("NO_COLOR").is_some_and(|v| !v.is_empty())
}

/// Paints the mark with the live theme and the live spin pose, honouring `ui.background_mark`, `NO_COLOR` and the detected colour level.
pub(super) fn paint_live(buf: &mut Buffer, screen: Rect, region: Rect, theme: &Theme) -> bool {
    if !crate::appearance::cache::load_background_mark() || no_color_env() {
        return false;
    }
    let level = color_support::get();
    if !level.has_color() || pick_size(screen, region).is_none() {
        return false;
    }
    let drew = paint(
        buf,
        screen,
        region,
        &MarkSpec {
            bg: theme.bg_base,
            fg: theme.text_primary,
            level,
            pose: super::wind_spin::current_pose(),
        },
    );
    if drew {
        super::wind_spin::note_painted();
    }
    drew
}

